package com.telecom.tollfree.service;
import com.telecom.tollfree.api.ApiModels.*; import com.telecom.tollfree.domain.*; import com.telecom.tollfree.messaging.*; import com.telecom.tollfree.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.Instant;
@Service @Transactional public class ProvisioningService { private final ProvisioningRequestRepository requests; private final CustomerService customers; private final NumberService numbers; private final NumberEventPublisher events; public ProvisioningService(ProvisioningRequestRepository r,CustomerService c,NumberService n,NumberEventPublisher e){requests=r;customers=c;numbers=n;events=e;} private ProvisionView replay(ProvisioningRequest r,String number){return new ProvisionView(r.getId(),number,numbers.status(number).status(),true);} public ProvisionView provision(ProvisionInput in){var existing=requests.findByCustomerIdAndNumber(in.customerId(),in.number());if(existing.isPresent())return replay(existing.get(),in.number()); try {Customer c=customers.require(in.customerId());NumberView number=numbers.reserve(in.number(),c);ProvisioningRequest request=requests.save(new ProvisioningRequest(c.getId(),in.number()));return new ProvisionView(request.getId(),number.number(),number.status(),false);}catch(ConflictException e){var concurrent=requests.findByCustomerIdAndNumber(in.customerId(),in.number());if(concurrent.isPresent())return replay(concurrent.get(),in.number());events.publish(new NumberEvent("ProvisioningFailed",in.number(),in.customerId(),Instant.now()));throw e;}catch(RuntimeException e){events.publish(new NumberEvent("ProvisioningFailed",in.number(),in.customerId(),Instant.now()));throw e;} } }
